//! 🎧️ Original audio channels and scalar indexes share one retained relational prefix.
use super::{SemioAudioSnapshot,SemioAudioFormat,SemioAudioChannel,SemioAudioTag,identity};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioAudioSnapshot>,validation:SchemaValidationStorage,channels:RowIndexStorage,samples:RowIndexStorage,tags:RowIndexStorage,order:Vec<usize>,tag_order:Vec<usize>,grouped:Vec<usize>}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),channels:RowIndexStorage::empty(),samples:RowIndexStorage::empty(),tags:RowIndexStorage::empty(),order:Vec::new(),tag_order:Vec::new(),grouped:Vec::new()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioAudioSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioAudioSnapshot::SQLITE_SCHEMA,phase,control)?;let document=database.table("semio_audio_document")?.single_row()?;identity(document,4)?;if document.rowid!=1{return Err(invalid("invalid Semio audio document identifier"))}let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.sample_rate=u32::try_from(document.integer(2)?).map_err(|_|invalid("invalid Semio audio sample rate"))?;snapshot.format=match document.text(3)?{"pcm8"=>SemioAudioFormat::Pcm8,"pcm16"=>SemioAudioFormat::Pcm16,"pcm24"=>SemioAudioFormat::Pcm24,"pcm32"=>SemioAudioFormat::Pcm32,"f32"=>SemioAudioFormat::Float32,"f64"=>SemioAudioFormat::Float64,_=>return Err(invalid("unknown Semio audio sample format"))};
 let channels=RowIndex::new(&mut prefix.channels,database,"semio_audio_channel",3,&[],control,"invalid Semio audio channel owner or identifier")?;let samples=RowIndex::new(&mut prefix.samples,database,"semio_audio_sample",5,&[],control,"invalid Semio sample channel or identifier")?;let tags=RowIndex::new(&mut prefix.tags,database,"semio_audio_tag",5,&[],control,"invalid Semio audio tag owner or identifier")?;channels.ordered_into(&mut prefix.order,2,control,"Semio audio channel ordinals must be contiguous")?;tags.ordered_into(&mut prefix.tag_order,2,control,"Semio audio tag ordinals must be contiguous")?;
 for(count,&index)in channels.indices().iter().enumerate(){if channels.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio audio channel owner or identifier"))}control.checkpoint(phase,count+1,channels.len())?;}for(count,&index)in samples.indices().iter().enumerate(){let row=samples.row(index)?;if channels.get(row.integer(1)?,control)?.is_none(){return Err(invalid("invalid Semio sample channel or identifier"))}row.integer(2)?;control.checkpoint(phase,count+1,samples.len())?;}samples.grouped_by_into(&mut prefix.grouped,2,control,"Semio audio sample ordinals must be contiguous",|row|Ok((0,Some(row.integer(1)?))))?;
 snapshot.channels=reserve(prefix.order.len(),control)?;snapshot.tags=reserve(prefix.tag_order.len(),control)?;let mut completed=0;for &index in &prefix.order{let row=channels.row(index)?;let range=samples.range_by(&prefix.grouped,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;snapshot.channels.push(SemioAudioChannel{samples:Vec::new()});let channel=snapshot.channels.last_mut().unwrap();channel.samples=reserve(range.len(),control)?;for position in range{let row=samples.row(prefix.grouped[position])?;let bits=u32::try_from(row.integer(4)?).map_err(|_|invalid("invalid Semio audio sample bits"))?;let value=f32::from_bits(bits);if value.is_nan(){if row.values[3]!=SqliteValue::Null{return Err(invalid("NaN Semio sample must have NULL numeric value"))}}else if row.real(3)?!=f64::from(value){return Err(invalid("Semio sample value disagrees with IEEE754 bits"))}channel.samples.push(value);completed+=1;control.checkpoint(phase,completed,0)?;}}
 for &index in &prefix.tag_order{let row=tags.row(index)?;if row.integer(1)?!=1{return Err(invalid("invalid Semio audio tag owner or identifier"))}snapshot.tags.push(SemioAudioTag{key:String::new(),value:String::new()});let tag=snapshot.tags.last_mut().unwrap();reconstruct_text_into(&mut tag.key,control,row.text(3)?)?;reconstruct_text_into(&mut tag.value,control,row.text(4)?)?;completed+=1;control.checkpoint(phase,completed,0)?;}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,completed,completed)
},|prefix|prefix.snapshot.take().unwrap())}
